#!/usr/bin/env node
// M7 consolidated gold evaluation report: runs every audited corpus against
// its gold set and writes docs/gold-evaluation-report.v1.json. The report is
// regenerated by this script only - never hand-edited - so the numbers are
// reproducible from the pinned SHAs. Corpora whose semantic gates fail closed
// (expected for partial-capability inputs) are recorded with their exit
// status instead of aborting the report.
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { evaluateCorpusGold, corpusGoldSetSchema, corpusGoldEvaluationSchema, type CorpusGoldArtifacts } from "../src/core/architecture/corpus-gold.js";

const root = fileURLToPath(new URL("..", import.meta.url));
const cliPath = join(root, "dist/cli.js");
const workDir = join(root, ".repomap/validation/gold-report");

interface CorpusDefinition {
  corpusId: string;
  repository: string;
  revision: string;
  include?: string;
  goldPath: string;
  /** The full-view gates are expected to fail closed for this corpus. */
  expectedGateFailure?: string;
}

const corpora: CorpusDefinition[] = [
  { corpusId: "fastapi-template", repository: "tiangolo/full-stack-fastapi-template", revision: "aabb90126964a164e02aff39e7c385bb0598236d", include: "backend/**", goldPath: "docs/gold/fastapi-template.v1.json" },
  { corpusId: "click", repository: "pallets/click", revision: "8abb77a8432e03ed14a95f972b44f905279415a7", goldPath: "docs/gold/click.v1.json", expectedGateFailure: "dynamic-import omission blocks full-view gates by design; the module graph artifact is complete" },
  { corpusId: "black", repository: "psf/black", revision: "b4f1fcae48826790b6f93ca9226d20003bce0eaa", goldPath: "docs/gold/black.v1.json" },
  { corpusId: "authelia", repository: "authelia/authelia", revision: "32b0bdac395efc707bc098757afa232177965736", goldPath: "docs/gold/authelia.v1.json" },
];

if (!existsSync(cliPath)) {
  console.error("dist/cli.js is missing; run npm run build first");
  process.exit(2);
}
mkdirSync(workDir, { recursive: true });

function readJson(path: string) {
  return JSON.parse(readFileSync(path, "utf8"));
}

interface CorpusResult {
  corpusId: string;
  repository: string;
  revision: string;
  analyzeExitCode: number;
  gateFailure: string | undefined;
  evaluation: ReturnType<typeof evaluateCorpusGold>;
}

const results: CorpusResult[] = [];
for (const corpus of corpora) {
  const outDir = join(workDir, corpus.corpusId);
  const args = ["analyze", `${corpus.repository}@${corpus.revision}`, "--no-render", "--out", outDir];
  if (corpus.include) args.push("--include", corpus.include);
  const analyze = spawnSync("node", [cliPath, ...args], {
    cwd: root,
    encoding: "utf8",
    timeout: 600000,
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, REPOMAP_CACHE_DIR: join(root, ".repomap/cache") },
  });
  if (!existsSync(join(outDir, "architecture.module-graph.json")) || !existsSync(join(outDir, "architecture.ir.json"))) {
    console.error(`${corpus.corpusId}: analysis produced no artifacts (exit ${analyze.status})`);
    process.exit(1);
  }

  const ir = readJson(join(outDir, "architecture.ir.json"));
  const moduleGraph = readJson(join(outDir, "architecture.module-graph.json"));
  const routeGraph = readJson(join(outDir, "architecture.route-graph.json"));
  const asyncGraph = readJson(join(outDir, "architecture.async-graph.json"));
  const evidence = readJson(join(outDir, "architecture.evidence.json"));
  const artifacts: CorpusGoldArtifacts = {
    revision: ir.revision,
    modules: moduleGraph.nodes.map((node: Record<string, unknown>) => ({ id: node.id as string, path: node.path as string, language: node.language as string | undefined, evidenceIds: ((node.evidenceIds as string[] | undefined)) ?? [] })),
    moduleEdges: moduleGraph.edges.map((edge: Record<string, unknown>) => ({ id: edge.id as string, from: edge.from as string, to: edge.to as string, toKind: edge.toKind as string, kind: edge.kind as string, path: edge.path as string, line: edge.line as number | undefined, evidenceIds: edge.evidenceIds as string[] })),
    cycles: moduleGraph.cycles.map((cycle: { nodes: string[] }) => ({
      memberPaths: cycle.nodes.map((nodeId: string) => {
        const node = moduleGraph.nodes.find((item: Record<string, unknown>) => item.id === nodeId);
        if (!node) throw new Error(`Cycle references unknown module node: ${nodeId}`);
        return node.path as string;
      }),
    })),
    routes: routeGraph.routes.map((route: Record<string, unknown>) => ({ id: route.id as string, method: route.method as string, path: route.path as string, sourcePath: route.sourcePath as string, line: route.line as number | undefined, evidenceIds: route.evidenceIds as string[] })),
    routeHandlers: Object.values(routeGraph.handlers as Record<string, Record<string, unknown>>).map((handler) => ({ id: handler.id as string, sourcePath: handler.sourcePath as string, line: handler.line as number | undefined, evidenceIds: handler.evidenceIds as string[] })),
    routeEdges: routeGraph.edges,
    sqlOperations: ir.operations.filter((operation: Record<string, unknown>) => operation.kind === "sql").map((operation: Record<string, unknown>) => ({ id: operation.id as string, action: operation.action as string, callSite: operation.callSite as string, driver: operation.driver as string | undefined, evidenceIds: operation.evidenceIds as string[] })),
    asyncOperations: asyncGraph.operations.map((operation: Record<string, unknown>) => ({ id: operation.id as string, action: operation.action as string, callSite: operation.callSite as string, topic: operation.topic as string | undefined, evidenceIds: operation.evidenceIds as string[] })),
    declarations: ir.declarations.map((declaration: Record<string, unknown>) => ({ declarationId: declaration.declarationId as string, sourcePath: declaration.sourcePath as string, detail: declaration.detail as string, evidenceIds: declaration.evidenceIds as string[] })),
    evidencePathsById: new Map(evidence.records.map((record: { id: string; path: string }) => [record.id, record.path])),
    omissions: {
      routeGraph: Array.isArray(routeGraph.omissions) ? routeGraph.omissions.length : 0,
      asyncGraph: Array.isArray(asyncGraph.omissions) ? asyncGraph.omissions.length : 0,
      ir: Array.isArray(ir.omissions) ? ir.omissions.length : 0,
    },
  };

  const gold = corpusGoldSetSchema.parse(readJson(resolve(root, corpus.goldPath)));
  const evaluation = corpusGoldEvaluationSchema.parse(evaluateCorpusGold(artifacts, gold));
  results.push({
    corpusId: corpus.corpusId,
    repository: `${corpus.repository}@${corpus.revision}`,
    revision: corpus.revision,
    analyzeExitCode: analyze.status ?? 1,
    gateFailure: corpus.expectedGateFailure,
    evaluation,
  });
  console.error(`${corpus.corpusId}: passed=${evaluation.passed} recall=${evaluation.recall.covered}/${evaluation.recall.total} FP=${evaluation.precision.suspectedFalsePositives.length}`);
}

const allPassed = results.every((result) => result.evaluation.passed);
const report = {
  version: 1,
  generatedAt: new Date().toISOString().slice(0, 10),
  generator: "scripts/gold-report.ts (npm run gold:report); regenerate, never hand-edit",
  allPassed,
  totals: {
    corpora: results.length,
    criticalFacts: results.reduce((total, result) => total + result.evaluation.recall.total, 0),
    covered: results.reduce((total, result) => total + result.evaluation.recall.covered, 0),
    suspectedFalsePositives: results.reduce((total, result) => total + result.evaluation.precision.suspectedFalsePositives.length, 0),
    evidenceInvalid: results.reduce((total, result) => total + result.evaluation.evidence.invalid.length, 0),
  },
  corpora: results,
};
writeFileSync(resolve(root, "docs/gold-evaluation-report.v1.json"), `${JSON.stringify(report, null, 2)}\n`);
console.log(JSON.stringify(report.totals));
process.exit(allPassed ? 0 : 1);
